import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForMat2,validMat2,advanceMat2,numericMat2,experimentOptions,experimentResult,experimentCases,experimentValid,predictionValid,outputLabel}from './mat2-models.js?v=20261023-physicscomplete01';import{showMat2}from './mat2-visuals.js?v=20261023-physicscomplete01';export{showMat2};
export function mountMat2(l,p,root,{save,done,feedback}){let ts=tasksForMat2(l.widget.slice(5),l.learnerTier),w=p.widget;w.mat2Task??=ts[0].id;w.mat2Drafts??={};w.mat2Passed??=[];let i=ts.findIndex(t=>t.id===w.mat2Task);if(i<0)i=0;let t=ts[i],v=w.mat2Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountMat2(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.mat2Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('mat2Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('mat2Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealMat2">Reveal evidence →</button><p id="mat2Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showMat2(t.kind,{state:c[0],context:'comparison',title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#mat2Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validMat2(c,v.answer);}
else if(t.type==='sequence'){body=field('mat2Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceMat2">Advance pathway →</button><p id="mat2Readout" aria-live="polite"></p>';draw=()=>{showMat2(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#mat2Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('mat2A',o.labels[0],o.a,v.a)+field('mat2B',o.labels[1],o.b,v.b)+(o.choices?field('mat2Prediction','Predict / '+o.unit,o.choices,v.prediction):'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="mat2Prediction" value="'+(v.prediction??'')+'"></label>')+'<button class="secondary" id="mat2Run">Reveal model output →</button><p id="mat2Output"></p>'+field('mat2Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showMat2(t.kind,{a:v.a,b:v.b,wiring:v.wiring,revealed:v.ran,title:t.title});$('#mat2Output').textContent=v.ran?'Model output: '+outputLabel(t.experiment,r.value):'Predict first. Use the selected quantities and the relationship explained in Discover.';};valid=()=>!!v.ran&&predictionValid(t.experiment,v.prediction,experimentResult(t.experiment,v.a,v.b));}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="mat2Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="mat2Number" type="number" step="any" value="'+(v.number??'')+'">'+field('mat2Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showMat2(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericMat2(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="mat2Evidence"></p><div class="lab-actions"><button class="secondary" id="recordMat2">Record reasoning</button><button class="secondary" id="nextMat2">Next challenge →</button></div><p id="mat2Progress"></p>';
const status=()=>{$('#mat2Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.mat2Passed.includes(t.id)?'Challenge recorded.':'';$('#mat2Progress').textContent=ts.filter(t=>w.mat2Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='mat2A'||id==='mat2B'){if(!val){remount();return;}v[id==='mat2A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='mat2Interpretation'){v.interpretation=val;save();return;}if(id==='mat2Prediction'){v.prediction=val;save();return;}if(id==='mat2Case'){if(val===''){remount();return;}v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='mat2Answer')v.answer=val;else if(id==='mat2Next')v.next=val;else if(id==='mat2Number')v.number=val;else if(id==='mat2Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='mat2Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#mat2Run'))$('#mat2Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Make a prediction first.',true);return;}v.ran=true;save();draw();};
if($('#revealMat2'))$('#revealMat2').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validMat2(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validMat2(t.cases[v.case],v.answer));};
if($('#advanceMat2'))$('#advanceMat2').onclick=()=>{let n=advanceMat2(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordMat2').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.mat2Passed.includes(t.id))w.mat2Passed.push(t.id);p.widgetDone=ts.every(t=>w.mat2Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextMat2').onclick=()=>{if(!w.mat2Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.mat2Task=ts[(i+1)%ts.length].id;save();remount();};}
